const shuffle = (list) => {
  const copy = [...list];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
};

// As perguntas da última partida de cada quiz (por ilha e nível), enquanto o site está aberto: a próxima
// tentativa prefere as que ainda não saíram, para refazer um nível não repetir sempre as mesmas.
const lastRound = new Map();

/** Guarda as perguntas de uma partida que saiu da tela, para a próxima com a mesma chave evitar repeti-las. */
export function rememberRound(memory, round) {
  lastRound.set(memory, new Set(round.map((q) => q.q)));
}

/**
 * Monta uma partida: sorteia as perguntas e embaralha as alternativas de cada uma.
 * "levels" escolhe as dificuldades (ex.: [1, 2]); "level" escolhe uma só; sem nenhum dos dois, vale tudo.
 * "memory" (opcional) é a chave de um quiz: a partida deixa para o fim as perguntas guardadas por rememberRound.
 * Com mais de uma dificuldade, a partida vai das mais fáceis para as mais difíceis.
 */
export function buildRound({ topic = null, level = null, levels = null, size = 5, memory = null }) {
  const allowed = levels ?? (level ? [level] : null);
  const pool = quizBank.filter((q) => (!topic || q.topic === topic) && (!allowed || allowed.includes(q.level)));
  const seen = (memory && lastRound.get(memory)) || new Set();
  const fresh = shuffle(pool.filter((q) => !seen.has(q.q)));
  const repeated = shuffle(pool.filter((q) => seen.has(q.q)));
  return [...fresh, ...repeated]
    .slice(0, size)
    .sort((a, b) => a.level - b.level)
    .map((q) => {
      const options = shuffle([q.a, ...q.w]);
      return { ...q, options, answer: options.indexOf(q.a) };
    });
}
